package com.example.budgetapp.ui.stats;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import androidx.annotation.*;
import androidx.fragment.app.Fragment;
import com.example.budgetapp.*;
import com.example.budgetapp.processing.*;
import java.time.*;
import java.util.*;
public final class StatsFragment extends Fragment {
 private StatsViewModel vm;
 public StatsFragment(){super(R.layout.fragment_stats);}
 @Override public void onViewCreated(@NonNull View view,@Nullable Bundle state){MainActivity activity=(MainActivity)requireActivity();vm=activity.statsViewModel();view.findViewById(R.id.stats_chart_help).setOnClickListener(v->{View values=view.findViewById(R.id.stats_trend_values);values.setVisibility(values.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);});
 view.findViewById(R.id.stats_expense).setOnClickListener(v->vm.setMetric(LedgerFilter.Metric.EXPENSE));
 view.findViewById(R.id.stats_income).setOnClickListener(v->vm.setMetric(LedgerFilter.Metric.INCOME));
 view.findViewById(R.id.stats_month).setOnClickListener(v->com.example.budgetapp.ui.common.MonthPicker.show(requireContext(),vm.month(),YearMonth.now(vm.app.clock.withZone(TimeWindows.LEDGER_ZONE)),vm::setMonth));
 view.findViewById(R.id.stats_dates).setOnClickListener(v->{LocalDate first=LocalDate.parse(vm.startDate());new android.app.DatePickerDialog(requireContext(),(picker,y,m,d)->{LocalDate startDate=LocalDate.of(y,m+1,d);LocalDate last=LocalDate.parse(vm.endDate());new android.app.DatePickerDialog(requireContext(),(endPicker,ey,em,ed)->{try{vm.setCustomDates(startDate,LocalDate.of(ey,em+1,ed));}catch(RuntimeException invalid){Toast.makeText(requireContext(),R.string.entry_invalid,Toast.LENGTH_LONG).show();}},last.getYear(),last.getMonthValue()-1,last.getDayOfMonth()).show();},first.getYear(),first.getMonthValue()-1,first.getDayOfMonth()).show();});
view.findViewById(R.id.stats_previous).setOnClickListener(v->vm.setMonth(vm.month().minusMonths(1)));view.findViewById(R.id.stats_next).setOnClickListener(v->vm.setMonth(vm.month().plusMonths(1)));view.findViewById(R.id.stats_six).setOnClickListener(v->vm.setMonthCount(6));view.findViewById(R.id.stats_twelve).setOnClickListener(v->vm.setMonthCount(12));spinner(view,R.id.stats_metric,new String[]{getString(R.string.overview_expense),getString(R.string.overview_income),getString(R.string.overview_net)},vm.metric().ordinal(),position->vm.setMetric(LedgerFilter.Metric.values()[position]));String[] providers={null,"WECHAT","ALIPAY","OTHER"};spinner(view,R.id.stats_provider,new String[]{getString(R.string.stats_all_providers),getString(R.string.platform_wechat),getString(R.string.platform_alipay),getString(R.string.entry_other)},Arrays.asList(providers).indexOf(vm.provider()),position->vm.setScope(vm.category(),providers[position]));EditText start=view.findViewById(R.id.stats_start),end=view.findViewById(R.id.stats_end);start.setText(vm.startDate());end.setText(vm.endDate());view.findViewById(R.id.stats_apply).setOnClickListener(v->{try{vm.setCustomDates(LocalDate.parse(start.getText().toString()),LocalDate.parse(end.getText().toString()));}catch(RuntimeException invalid){end.setError(getString(R.string.entry_invalid));}});view.findViewById(R.id.stats_month_mode).setOnClickListener(v->vm.clearCustomRange());
  vm.error.observe(getViewLifecycleOwner(),error->((TextView)view.findViewById(R.id.stats_error)).setText(Boolean.TRUE.equals(error)?getString(R.string.stats_error):""));
  vm.display().observe(getViewLifecycleOwner(),display->{view.findViewById(R.id.stats_expense).setSelected(vm.metric()==LedgerFilter.Metric.EXPENSE);view.findViewById(R.id.stats_income).setSelected(vm.metric()==LedgerFilter.Metric.INCOME);((TextView)view.findViewById(R.id.stats_error)).setText("");((TextView)view.findViewById(R.id.stats_month)).setText(vm.month().getYear()+"年"+vm.month().getMonthValue()+"月 ▾");view.findViewById(R.id.stats_next).setEnabled(vm.month().isBefore(YearMonth.now(vm.app.clock.withZone(TimeWindows.LEDGER_ZONE))));view.findViewById(R.id.stats_six).setSelected(vm.monthCount()==6);view.findViewById(R.id.stats_twelve).setSelected(vm.monthCount()==12);((TextView)view.findViewById(R.id.stats_total)).setText("¥ "+Money.formatFen(display.snapshot.valueFen));((TextView)view.findViewById(R.id.stats_scope)).setText(getString(R.string.stats_scope,Instant.ofEpochMilli(display.snapshot.filter.startMs).atZone(TimeWindows.LEDGER_ZONE).toLocalDate().toString(),Instant.ofEpochMilli(Math.max(display.snapshot.filter.startMs,display.snapshot.filter.endMs-1)).atZone(TimeWindows.LEDGER_ZONE).toLocalDate().toString()));String comparison="";if(display.comparison!=null){if(display.snapshot.filter.metric==LedgerFilter.Metric.EXPENSE){var result=display.comparison.spending;comparison=result.label+(result.percent==null?"":getString(R.string.comparison_percent,result.percent.toPlainString()));}else comparison=getString(R.string.comparison_other_values,Money.formatFen(display.comparison.incomeDeltaFen),Money.formatFen(display.comparison.netDeltaFen));}((TextView)view.findViewById(R.id.stats_comparison)).setText(comparison);
   List<String> categoryIds=new ArrayList<>(),labels=new ArrayList<>();categoryIds.add(null);labels.add(getString(R.string.stats_all_categories));for(var c:display.categories){categoryIds.add(c.id);labels.add(c.name);}spinner(view,R.id.stats_category,labels.toArray(new String[0]),categoryIds.indexOf(vm.category()),position->vm.setScope(categoryIds.get(position),vm.provider()));
   String trendName="全部分类";for(var category:display.categories)if(category.id.equals(vm.category()))trendName=category.name;long trendTotal=0;if(vm.custom()){for(var point:display.trend)trendTotal=Math.addExact(trendTotal,point.valueFen);}else{for(var point:display.trend)if(point.month.equals(vm.month()))trendTotal=point.valueFen;}((TextView)view.findViewById(R.id.stats_trend_current)).setText((vm.custom()?"所选范围":vm.month().getMonthValue()+"月")+" · "+trendName+"    ¥ "+Money.formatFen(trendTotal));
   BudgetChartView trend=view.findViewById(R.id.stats_trend_chart);List<BudgetChartView.ChartItem> trendItems=new ArrayList<>();LinearLayout values=view.findViewById(R.id.stats_trend_values);values.removeAllViews();for(var point:display.trend){trendItems.add(new BudgetChartView.ChartItem(getString(R.string.stats_month_label,point.month.getMonthValue()),point.valueFen,point.filter));row(values,getString(R.string.stats_point,point.month.toString(),Money.formatFen(point.valueFen),point.inProgress?" · "+getString(R.string.stats_as_of):""),()->activity.showLedger(point.filter));}trend.setItems(trendItems,activity::showLedger);
   boolean income=display.snapshot.filter.metric==LedgerFilter.Metric.INCOME;
   view.findViewById(R.id.stats_category_section).setVisibility(display.snapshot.filter.metric==LedgerFilter.Metric.NET_OUTFLOW?View.GONE:View.VISIBLE);
   long categoryTotal=income?display.snapshot.incomeFen:display.snapshot.expenseFen;
   view.findViewById(R.id.stats_category_empty).setVisibility(categoryTotal==0?View.VISIBLE:View.GONE);
   LinearLayout categories=view.findViewById(R.id.stats_category_values);categories.removeAllViews();
   java.util.Map<String,Long> grouped=new java.util.LinkedHashMap<>();
   if(income){for(var entry:display.snapshot.entries){var tx=entry.transaction;grouped.merge(tx.categoryId,tx.amountMinor,Math::addExact);}}else for(var category:display.snapshot.categories)grouped.put(category.categoryId,category.amountFen);
   java.util.List<java.util.Map.Entry<String,Long>> categoryRows=new java.util.ArrayList<>(grouped.entrySet());categoryRows.sort(java.util.Map.Entry.<String,Long>comparingByValue().reversed());
   for(var entry:categoryRows){String name="未分类";for(var c:display.categories)if(c.id.equals(entry.getKey()))name=c.name;long amount=entry.getValue();java.math.BigDecimal share=categoryTotal==0?java.math.BigDecimal.ZERO:java.math.BigDecimal.valueOf(amount).multiply(java.math.BigDecimal.valueOf(100)).divide(java.math.BigDecimal.valueOf(categoryTotal),1,java.math.RoundingMode.HALF_UP);
    LedgerFilter filter=new LedgerFilter(display.snapshot.filter.startMs,display.snapshot.filter.endMs,income?LedgerFilter.Metric.INCOME:LedgerFilter.Metric.EXPENSE,entry.getKey(),display.snapshot.filter.provider);
    row(categories,name+"    ¥ "+Money.formatFen(amount)+"    "+share.toPlainString()+"%",()->activity.showLedger(filter));
    ProgressBar progress=new ProgressBar(requireContext(),null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setProgress(share.multiply(java.math.BigDecimal.TEN).intValue());progress.setProgressTintList(android.content.res.ColorStateList.valueOf(requireContext().getColor(R.color.obs_green)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,Math.round(3*getResources().getDisplayMetrics().density));lp.bottomMargin=Math.round(10*getResources().getDisplayMetrics().density);categories.addView(progress,lp);
   }
   view.findViewById(R.id.stats_comparison).setVisibility(vm.custom()||income?View.GONE:View.VISIBLE);
   TextView changes=view.findViewById(R.id.stats_changes);changes.setVisibility(vm.custom()||income?View.GONE:View.VISIBLE);changes.setText("变化在哪里\n\n"+(display.comparison==null?"暂无可比数据":display.comparison.spending.explanation));

  });vm.refresh();
 }
 private void row(LinearLayout parent,String label,Runnable action){Button row=(Button)getLayoutInflater().inflate(R.layout.item_stats_value,parent,false);row.setText(label);row.setOnClickListener(v->action.run());parent.addView(row);}
 private void spinner(View view,int id,String[] labels,int selected,java.util.function.IntConsumer action){Spinner spinner=view.findViewById(id);spinner.setOnItemSelectedListener(null);ArrayAdapter<String> adapter=new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(Math.max(0,selected));spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,View v,int position,long row){action.accept(position);}});}
}
